def min_insertions(s: str) -> int:
    open_count = 0   # '(' seen so far that are still unmatched
    need = 0         # ')' seen with no '(' available to match them
    for ch in s:
        if ch == '(':
            open_count += 1
        else:
            if open_count > 0:
                open_count -= 1   # this ')' cancels an earlier '('
            else:
                need += 1         # unmatchable ')' - needs a '(' inserted
    # leftover '(' each need a ')', leftover ')' each need a '('
    return need + open_count

