class Solution {
    public int minInsertions(String s) {
        int open = 0;   // '(' seen so far that are still unmatched
        int need = 0;   // ')' seen with no '(' available to match them
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == '(') {
                open++;
            } else if (open > 0) {
                open--;      // this ')' cancels an earlier '('
            } else {
                need++;      // unmatchable ')' - needs a '(' inserted
            }
        }
        return need + open;
    }
}

