import java.util.*;

class Solution {
    public List<String> topKSources(String[] sources, int k) {
        Map<String, Integer> counts = new HashMap<>();
        for (String s : sources) {
            counts.put(s, counts.getOrDefault(s, 0) + 1);
        }

        // Min-heap of size k: the entry that would lose the final ranking
        // sits on top, so it is the one evicted when we overflow.
        PriorityQueue<Map.Entry<String, Integer>> heap = new PriorityQueue<>(
            (a, b) -> {
                if (!a.getValue().equals(b.getValue())) {
                    return a.getValue() - b.getValue();      // smaller count first
                }
                return b.getKey().compareTo(a.getKey());     // larger name first
            }
        );

        for (Map.Entry<String, Integer> e : counts.entrySet()) {
            heap.offer(e);
            if (heap.size() > k) heap.poll();
        }

        List<Map.Entry<String, Integer>> survivors = new ArrayList<>(heap);
        survivors.sort((a, b) -> {
            if (!a.getValue().equals(b.getValue())) {
                return b.getValue() - a.getValue();          // count descending
            }
            return a.getKey().compareTo(b.getKey());          // name ascending
        });

        List<String> out = new ArrayList<>();
        for (Map.Entry<String, Integer> e : survivors) out.add(e.getKey());
        return out;
    }
}

