#include <string>
#include <vector>
#include <unordered_map>
#include <queue>
#include <algorithm>

class Solution {
public:
    std::vector<std::string> topKSources(const std::vector<std::string>& sources, int k) {
        std::unordered_map<std::string, int> counts;
        for (const auto& s : sources) ++counts[s];

        using Entry = std::pair<int, std::string>;   // (count, name)

        // Comparator returns true when a should sit BELOW b in the heap.
        // We want the losing entry on top: smallest count, then largest name.
        auto worseOnTop = [](const Entry& a, const Entry& b) {
            if (a.first != b.first) return a.first > b.first;   // smaller count on top
            return a.second < b.second;                          // larger name on top
        };

        std::priority_queue<Entry, std::vector<Entry>, decltype(worseOnTop)> heap(worseOnTop);
        for (const auto& kv : counts) {
            heap.push({kv.second, kv.first});
            if (static_cast<int>(heap.size()) > k) heap.pop();
        }

        std::vector<Entry> survivors;
        while (!heap.empty()) { survivors.push_back(heap.top()); heap.pop(); }

        std::sort(survivors.begin(), survivors.end(), [](const Entry& a, const Entry& b) {
            if (a.first != b.first) return a.first > b.first;   // count descending
            return a.second < b.second;                          // name ascending
        });

        std::vector<std::string> out;
        out.reserve(survivors.size());
        for (const auto& e : survivors) out.push_back(e.second);
        return out;
    }
};

