import java.util.*;

class Solution {
    public int[][] merge(int[][] intervals) {
        if (intervals.length == 0) return new int[0][];

        // Comparator.comparingInt avoids the a[0] - b[0] overflow trap
        // when start values can be near Integer.MAX_VALUE.
        Arrays.sort(intervals, Comparator.comparingInt(a -> a[0]));

        List<int[]> merged = new ArrayList<>();
        int[] current = new int[]{intervals[0][0], intervals[0][1]};

        for (int i = 1; i < intervals.length; i++) {
            int start = intervals[i][0], end = intervals[i][1];
            if (start <= current[1]) {
                current[1] = Math.max(current[1], end);   // extend, never shrink
            } else {
                merged.add(current);
                current = new int[]{start, end};
            }
        }
        merged.add(current);   // the final open interval

        return merged.toArray(new int[merged.size()][]);
    }
}

