import java.util.*;

class Solution {
    public int[] daysUntilBetter(int[] scores) {
        int n = scores.length;
        int[] answer = new int[n];        // defaults to 0 = 'never beaten'
        Deque<Integer> stack = new ArrayDeque<>();   // indices still waiting

        for (int i = 0; i < n; i++) {
            // every pending day with a strictly smaller score is resolved by today
            while (!stack.isEmpty() && scores[stack.peek()] < scores[i]) {
                int j = stack.pop();
                answer[j] = i - j;
            }
            stack.push(i);
        }

        return answer;
    }
}

