from collections import deque
from typing import List

def count_regions(grid: List[List[str]]) -> int:
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    count = 0
    DIRECTIONS = ((1, 0), (-1, 0), (0, 1), (0, -1))

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != '1':
                continue

            count += 1
            # Iterative BFS, not recursion: a 300x300 grid of all '1's is a
            # single 90,000-cell region and would overflow the call stack.
            queue = deque([(r, c)])
            grid[r][c] = '0'          # sink on enqueue, never on dequeue

            while queue:
                cr, cc = queue.popleft()
                for dr, dc in DIRECTIONS:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '1':
                        grid[nr][nc] = '0'
                        queue.append((nr, nc))

    return count

