#include <vector>
#include <queue>

class Solution {
public:
    std::vector<int> rolloutOrder(int n, const std::vector<std::vector<int>>& dependencies) {
        std::vector<std::vector<int>> adjacency(n);
        std::vector<int> inDegree(n, 0);

        // [a, b] means 'b must ship before a', so the edge is b -> a
        for (const auto& dep : dependencies) {
            int a = dep[0], b = dep[1];
            adjacency[b].push_back(a);
            ++inDegree[a];
        }

        std::queue<int> q;
        for (int i = 0; i < n; ++i) {
            if (inDegree[i] == 0) q.push(i);
        }

        std::vector<int> order;
        order.reserve(n);

        while (!q.empty()) {
            int node = q.front();
            q.pop();
            order.push_back(node);
            for (int next : adjacency[node]) {
                if (--inDegree[next] == 0) q.push(next);
            }
        }

        // fewer than n emitted means the remainder sit in a cycle
        if (static_cast<int>(order.size()) != n) return {};
        return order;
    }
};

