class TreeNode:
    def __init__(self, val: int = 0, left: 'Optional[TreeNode]' = None, right: 'Optional[TreeNode]' = None):
        self.val = val
        self.left = left
        self.right = right


def right_side_view(root: Optional[TreeNode]) -> List[int]:
    if root is None:
        return []

    view = []
    queue = deque([root])

    while queue:
        level_size = len(queue)      # snapshot BEFORE enqueuing children
        for i in range(level_size):
            node = queue.popleft()
            if i == level_size - 1:  # last node at this depth is the visible one
                view.append(node.val)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)

    return view

